css.textContent+=`.insp-encouragement{margin:-5px 0 25px;text-align:center}#inspNeed{border-radius:30px!important;color:var(--iq-accent)!important;font-size:12px!important;padding:12px 20px!important}#inspMoodOptions[hidden]{display:none!important}#inspMoodOptions{margin:15px auto 0;max-width:720px;border:1px solid #ffffff14;border-radius:18px;padding:18px;background:#ffffff04}#inspMoodOptions p{font-size:12px;color:#cebcd5;line-height:1.7;margin:0 0 12px}#inspMoodOptions>div{display:flex;flex-wrap:wrap;justify-content:center;gap:7px}#inspMoodOptions button{font-size:11px!important;border-radius:25px!important}#inspMoodOptions button[aria-pressed=true]{background:var(--iq-accent)!important;color:var(--iq-bg)!important}#inspMoodOptions #inspMoodMessage{font-size:11px;margin:14px 0 0}#inspMoodMessage:empty{display:none}`;document.head.append(css);const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let savedData={},favorites=[],revision=0,loaded=false,busy=false,theme='all',favoritesOnly=false,current,selectedDaily=true,generation=0,mood='all';
const moodQuotes={tired:{magic:[3,5],camprock:[3,5],zombies:[1,5],descendentes:[4,5],frozen:[2,4],princess:[1,4]},unsure:{magic:[2,4],camprock:[1,5],zombies:[1,3],descendentes:[2,4],frozen:[3,5],princess:[2,5]},courage:{magic:[1,2],camprock:[2,4],zombies:[3,4],descendentes:[1,3],frozen:[1,3],princess:[3,5]}};
for(const [key,values]of Object.entries({life:{tired:[1,3],unsure:[5,6],courage:[2,5]},self:{tired:[1,2],unsure:[3,4],courage:[5,6]},restart:{tired:[2,5],unsure:[3,4],courage:[1,6]},work:{tired:[1,4],unsure:[2,6],courage:[3,5]},care:{tired:[1,5],unsure:[3,4],courage:[2,6]}})){for(const mood of ['tired','unsure','courage'])moodQuotes[mood][key]=values[mood];}
const moodWords={tired:['UM RESPIRO PARA VOCÊ','Você não precisa dar conta de tudo agora. Um passo no seu tempo já tem valor.'],unsure:['UM LEMBRETE DO SEU VALOR','A dúvida pode aparecer sem apagar o que você sabe e tudo o que já construiu.'],courage:['UM POUCO DE CORAGEM','Comece pelo passo possível. Você não precisa resolver o caminho inteiro hoje.']};
function moodPool(){return quotes.filter(q=>(theme==='all'||q.theme===theme)&&(mood==='all'||moodQuotes[mood][q.theme].some(n=>q.id===q.theme+'-'+n)))}
function nextEncouragement(){const pool=moodPool(),other=pool.filter(q=>q.id!==current.id);current=(other.length?other:pool)[Math.floor(Math.random()*(other.length||pool.length))]||current;selectedDaily=false;}

function daily(){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),date=['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-');let hash=0;for(const char of date)hash=(hash*31+char.charCodeAt(0))>>>0;return quotes[hash%quotes.length]}current=daily();window.alinyInspirationDaily=()=>{const quote=daily();return {text:quote.text,theme:themes[quote.theme].name,icon:themes[quote.theme].icon}};window.dispatchEvent(new Event('aliny-inspiration-ready'));
function status(t){$('inspStatus').textContent=t}function setBusy(b){busy=b;$('inspRefresh').disabled=b;$('inspFavoriteSpot').disabled=b;for(const button of root.querySelectorAll('[data-favorite],.insp-care-write'))button.disabled=b}
function render(){for(const b of root.querySelectorAll('[data-mood]'))b.setAttribute('aria-pressed',String(b.dataset.mood===mood));$('inspMoodMessage').textContent=mood==='all'?'':moodWords[mood][1];const palette=themes[current.theme];for(const [key,value]of Object.entries({accent:palette.accent,bg:palette.bg,card:palette.card}))root.style.setProperty('--iq-'+key,value);$('inspQuote').textContent=current.text;$('inspSpotLabel').textContent=palette.icon+' '+(selectedDaily?'FRASE DO DIA':mood!=='all'?moodWords[mood][0]:'SUA INSPIRAÇÃO')+' · '+palette.name.toLocaleUpperCase('pt-BR');$('inspThemeDescription').textContent=palette.description;$('inspFavoriteSpot').textContent=favorites.includes(current.id)?'♥ Favorita':'♡ Favoritar';$('inspFavoriteSpot').setAttribute('aria-pressed',String(favorites.includes(current.id)));$('inspFavoritesView').setAttribute('aria-pressed',String(favoritesOnly));$('inspFavoritesView').textContent='♡ Minhas favoritas · '+favorites.length;$('inspLibraryTitle').textContent=favoritesOnly?'Seu cantinho de favoritas':theme==='all'?'Explore as inspirações':themes[theme].name+' · Inspirações';$('inspThemes').innerHTML=[['all',{icon:'✧',name:'Todos'}],...['life','self','restart','work','care',...Object.keys(themes).filter(key=>!['life','self','restart','work','care'].includes(key))].map(key=>[key,themes[key]])].map(([id,t])=>`<button type="button" data-theme="${id}" aria-pressed="${theme===id}">${t.icon} ${t.name}</button>`).join('');const list=moodPool().filter(q=>!favoritesOnly||favorites.includes(q.id));$('inspCards').innerHTML=list.map(q=>`<article class="insp-card"><span>${themes[q.theme].icon} ${themes[q.theme].name.toLocaleUpperCase('pt-BR')}</span><p>${esc(q.text)}</p><div class="insp-card-actions"><button type="button" data-show="${q.id}">Ler em destaque</button><button type="button" data-favorite="${q.id}" aria-pressed="${favorites.includes(q.id)}" aria-label="${favorites.includes(q.id)?'Remover das favoritas':'Favoritar'}: ${esc(q.text)}">${favorites.includes(q.id)?'♥ Salva':'♡ Salvar'}</button></div></article>`).join('')||'<p class="insp-empty">'+(favoritesOnly?'Seu cantinho está esperando as primeiras favoritas.<br>Toque em ♡ Salvar nas frases que combinam com você.':'Nenhuma frase neste tema.')+'</p>';setBusy(busy)}
async function load(){if(busy)return;const request=++generation;setBusy(true);status('Buscando suas favoritas…');try{await window.alinyAuth.ready;const r=await window.alinyAuth.api('/api/inspira',{method:'GET'});if(!r.ok)throw Error('As frases estão disponíveis, mas não consegui carregar suas favoritas. Tente Sincronizar.');const result=await r.json();if(request!==generation)return;favorites=Array.isArray(result.data?.favorites)?[...new Set(result.data.favorites.filter(id=>ids.has(id)))]:[];savedData=result.data&&typeof result.data==='object'&&!Array.isArray(result.data)?result.data:{};revision=result.revision;loaded=true;render();renderLetters();renderCare();if(!$('inspColorWord').value)fillCareDay($('inspColorDate').value||careDate());status('Favoritas sincronizadas com sua conta. Frases originais para diferentes momentos da vida.')}catch(e){if(request===generation){loaded=false;status(e.message)}}finally{if(request===generation)setBusy(false)}}
async function favorite(id){if(busy)return;if(!loaded){status('Sincronize suas favoritas antes de salvar. Você pode continuar lendo e copiando as frases.');return}setBusy(true);status('Salvando favorita na sua conta…');const requestGeneration=generation,adding=!favorites.includes(id),next=adding?[...favorites,id]:favorites.filter(x=>x!==id);try{const r=await window.alinyAuth.api('/api/inspira',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,data:{...savedData,favorites:next}})});if(requestGeneration!==generation)return;if(r.status===409){loaded=false;throw Error('Suas favoritas mudaram em outro dispositivo. Clique em Sincronizar e tente de novo.')}if(!r.ok)throw Error('Não foi possível salvar a mudança online. Tente novamente.');const result=await r.json();if(requestGeneration!==generation)return;favorites=next;savedData={...savedData,favorites:next};revision=result.revision;render();status(adding?'Frase guardada nas suas favoritas. 💜':'Frase removida das favoritas.')}catch(e){if(requestGeneration===generation)status(e.message)}finally{if(requestGeneration===generation)setBusy(false)}}
$('inspThemes').onclick=e=>{const b=e.target.closest('[data-theme]');if(!b)return;theme=b.dataset.theme;if(mood!=='all')nextEncouragement();else if(theme!=='all'){current=quotes.find(q=>q.theme===theme);selectedDaily=false}render()};$('inspAnother').onclick=()=>{nextEncouragement();render()};$('inspDaily').onclick=()=>{current=daily();selectedDaily=true;theme='all';mood='all';render()};$('inspFavoritesView').onclick=()=>{favoritesOnly=!favoritesOnly;render()};$('inspFavoriteSpot').onclick=()=>favorite(current.id);$('inspCards').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.favorite)return favorite(b.dataset.favorite);if(b.dataset.show){current=quotes.find(q=>q.id===b.dataset.show)||current;selectedDaily=false;render();$('inspQuote').scrollIntoView({block:'center',behavior:'auto'})}};$('inspCopy').onclick=async()=>{try{await navigator.clipboard.writeText(current.text+'\n— Aliny Inspira · '+themes[current.theme].name);status('Frase copiada! Pronta para seu post-it ou mensagem. 💜')}catch{status('Não foi possível copiar automaticamente. Selecione o texto da frase e copie pelo menu do navegador.')}};$('inspRefresh').onclick=load;$('inspNeed').onclick=()=>{const options=$('inspMoodOptions');options.hidden=!options.hidden;$('inspNeed').setAttribute('aria-expanded',String(!options.hidden))};$('inspMoodOptions').onclick=e=>{const b=e.target.closest('[data-mood]');if(!b)return;mood=b.dataset.mood;nextEncouragement();render()};
function close(){root.hidden=true;document.body.classList.remove('inspira-visible')}$('inspBack').onclick=()=>{close();$('appsLauncher').click()};window.addEventListener('aliny-open-inspira',async()=>{root.hidden=false;document.body.classList.add('inspira-visible');current=daily();selectedDaily=true;mood='all';theme='all';render();await load()});window.addEventListener('aliny-close-inspira',close);new MutationObserver(()=>{if(document.body.classList.contains('auth-locked')){close();generation++;favorites=[];savedData={};loaded=false;clearLetterForm();resetCare();renderLetters();renderCare();revision=0;busy=false;render()}}).observe(document.body,{attributes:true,attributeFilter:['class']});

/* Post-its and a gentle daily celebration. */
const extras=document.createElement('section');
extras.className='insp-extras';
extras.innerHTML='<div><span class="insp-eyebrow">LEVE UM POUCO DE MAGIA</span><h2>Seu post-it de inspiração</h2><p>Use a frase em destaque e escolha uma cor. Imprima em tamanho de 7,6 × 7,6 cm e recorte.</p><div class="insp-note-options" role="group" aria-label="Cor do post-it"><button type="button" data-note-color="#fff2b3" aria-pressed="true">☀ Amarelo</button><button type="button" data-note-color="#eadcff" aria-pressed="false">✧ Lilás</button><button type="button" data-note-color="#ffdfeb" aria-pressed="false">♡ Rosa</button></div><button type="button" id="inspPrintNote" class="insp-primary">Imprimir frase em post-it</button></div><div><span class="insp-eyebrow">PEQUENOS PASSOS TAMBÉM CONTAM</span><h2>Uma conquista de hoje</h2><label for="inspWin">O que você conseguiu fazer, mesmo que pareça pequeno?</label><textarea id="inspWin" maxlength="240" rows="3" placeholder="Hoje eu consegui…"></textarea><button type="button" id="inspCelebrate">✦ Celebrar meu passo</button><p id="inspWinFeedback" role="status"></p><small>Um espaço para este momento: seu texto fica somente nesta tela e é apagado ao sair.</small></div>';
root.querySelector('.insp-library').before(extras);
css.textContent+='.insp-extras{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:20px 0 40px}.insp-extras>div{padding:24px;border:1px solid #ffffff18;border-radius:20px;background:#ffffff04}.insp-extras h2{font:26px Georgia,serif;margin:12px 0}.insp-extras p,.insp-extras label{font-size:12px;line-height:1.8;color:#d5c6dc}.insp-extras label{display:block}.insp-extras small{font-size:10px;color:#c1b0c4;line-height:1.7;display:block}.insp-extras textarea{display:block;resize:vertical;width:100%;font:14px/1.6 system-ui;color:#fff;background:#0002;border:1px solid #ffffff30;border-radius:12px;padding:12px;margin:12px 0}.insp-extras textarea:focus-visible{outline:2px solid var(--iq-accent)}.insp-note-options{display:flex;gap:6px;flex-wrap:wrap;margin:15px 0}.insp-note-options button[aria-pressed=true]{background:var(--iq-accent)!important;color:var(--iq-bg)!important}.insp-extras button{font-size:11px!important}@media(max-width:680px){.insp-extras{grid-template-columns:1fr}}';
