extras.onclick=e=>{const b=e.target.closest('[data-note-color]');if(!b)return;noteColor=b.dataset.noteColor;for(const item of extras.querySelectorAll('[data-note-color]'))item.setAttribute('aria-pressed',String(item===b));};
$('inspCelebrate').onclick=()=>{$('inspWinFeedback').textContent=$('inspWin').value.trim()?'Seu passo merece reconhecimento. Você pode se orgulhar do que fez hoje. 💜':'Vale algo simples: ter começado, pedido ajuda ou respeitado seu tempo. Qual foi seu passo?';};
$('inspPrintNote').onclick=()=>{
const frame=document.createElement('iframe');
frame.title='Impressão do post-it';frame.style.cssText='position:fixed;left:-10000px;width:1px;height:1px;border:0';
frame.onload=()=>{try{frame.contentWindow.focus();frame.contentWindow.print();status('Post-it pronto. Na impressão, use escala de 100% e ative os gráficos de fundo para manter a cor.');}catch{status('Não consegui abrir a impressão. Tente novamente pelo computador.');} };
frame.srcdoc='<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Post-it · Aliny Inspira</title><style>@page{size:A4 portrait;margin:15mm}*{box-sizing:border-box}body{margin:0;font-family:Georgia,serif}.note{width:76mm;height:76mm;padding:7mm;background:'+noteColor+';color:#30213d;border:1px dashed #847388;display:flex;flex-direction:column;justify-content:center;print-color-adjust:exact;-webkit-print-color-adjust:exact}p{font-size:14pt;line-height:1.35;margin:0 0 5mm;overflow-wrap:anywhere}small{font:8pt system-ui;line-height:1.5}</style><article class="note"><p>'+esc(current.text)+'</p><small>✧ ALINY INSPIRA<br>Tema: '+esc(themes[current.theme].name)+' · Frase original</small></article></html>';
for(const old of root.querySelectorAll('iframe[data-note-print]'))old.remove();
frame.dataset.notePrint='true';root.append(frame);
};
