const affection={
  gentle:{label:'Dias difíceis',notes:['Hoje você pode fazer menos e ainda merecer carinho.','Que tal tratar você com a mesma gentileza que oferece a quem ama?','Você pode procurar companhia. Não precisa atravessar tudo sozinha.','Um dia difícil não resume a sua história.']},
  brave:{label:'Um pouco de coragem',notes:['Seu próximo passo não precisa impressionar ninguém. Só precisa ser possível.','A sua voz merece espaço, mesmo quando sai baixinha.','Você pode tentar de novo com o que aprendeu até aqui.','Há caminhos bonitos que começam com um pequeno sim para você.']},
  smile:{label:'Só para sorrir',notes:['Bilhetinho oficial do seu potinho: um abraço imaginário acaba de chegar. 💜','Se o dia fosse um filme, esta seria a cena de uma pausa gostosa. ✨','Um lembrete pequenininho: tem espaço para alegria nas coisas simples.','Seu brilho também combina com cabelo bagunçado e um dia comum. ✧']}
};
const keepsakes=document.createElement('section');keepsakes.className='insp-keepsakes';
keepsakes.innerHTML=`<article class="insp-jar-card"><span class="insp-eyebrow">UM BILHETINHO PARA VOCÊ</span><h2>Potinho de carinho</h2><p>Escolha o carinho que você quer encontrar agora.</p><div class="insp-note-options" role="group" aria-label="Tipo de bilhetinho">${Object.entries(affection).map(([key,value])=>`<button type="button" data-affection="${key}" aria-pressed="${key==='gentle'}">${value.label}</button>`).join('')}</div><button type="button" id="inspOpenJar" class="insp-jar-button" aria-label="Abrir um bilhetinho do potinho"><span aria-hidden="true">✧<br>♡</span><b>Abrir um carinho</b></button><blockquote id="inspAffection" aria-live="polite">Um pequeno gesto de carinho cabe aqui.</blockquote><button type="button" id="inspCopyAffection" disabled>Copiar bilhetinho</button><p class="insp-fine">Bilhetes originais do Aliny Inspira.</p></article><article class="insp-letter-card"><span class="insp-eyebrow">PARA SEU PRÓXIMO CAPÍTULO</span><h2>Carta para mim no futuro</h2><p>Guarde um sonho, uma promessa gentil ou algo que você quer lembrar.</p><form id="inspLetterForm"><label for="inspLetterTitle">Título da carta</label><input id="inspLetterTitle" required maxlength="100" placeholder="Para a minha versão do futuro…"><label for="inspLetterDate">Uma data para reler (opcional)</label><input type="date" id="inspLetterDate"><label for="inspLetterText">Sua mensagem</label><textarea id="inspLetterText" required maxlength="5000" rows="6" placeholder="Querida eu do futuro…"></textarea><button type="submit" id="inspSaveLetter" class="insp-primary">♡ Guardar na minha conta</button></form><p class="insp-fine">Você pode reler quando quiser. A data é uma referência; não envia notificações. O rascunho fica nesta tela até você sair.</p><p id="inspLetterStatus" role="status"></p></article></section><section class="insp-saved-letters"><div class="insp-library-heading"><div><span class="insp-eyebrow">PALAVRAS QUE FICARAM</span><h2>Minhas cartas</h2></div></div><div id="inspLetters" class="insp-cards"></div></section><dialog id="inspReadLetter"><div class="insp-letter-dialog-top"><h2 id="inspReadTitle"></h2><button type="button" id="inspCloseLetter" aria-label="Fechar carta">✕</button></div><p id="inspReadDate" class="insp-fine"></p><div id="inspReadText"></div></dialog>`;
root.querySelector('.insp-library').before(keepsakes);
css.textContent+=`.insp-keepsakes{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-bottom:32px}.insp-keepsakes article{padding:26px;border:1px solid #ffffff20;border-radius:24px;background:#ffffff04}.insp-keepsakes h2,.insp-saved-letters h2{font:28px/1.2 Georgia,serif;margin:12px 0 16px}.insp-keepsakes p{font-size:12px;line-height:1.8;color:#d5c6dc}.insp-keepsakes .insp-fine,.insp-fine{font-size:10px;line-height:1.7;color:#c1b0c4}.insp-jar-card{text-align:center}.insp-jar-card .insp-note-options{justify-content:center}#alinyInspira .insp-jar-button{display:flex;flex-direction:column;align-items:center;justify-content:center;width:150px;min-height:170px;margin:26px auto 20px;border:2px solid var(--iq-accent);border-top:12px solid var(--iq-accent);border-radius:15px 15px 44px 44px;background:linear-gradient(135deg,#ffffff18,#ffffff03);color:var(--iq-accent);gap:10px}.insp-jar-button>span{font:42px/1 Georgia,serif}.insp-jar-button b{font-size:11px}.insp-jar-card blockquote{min-height:108px;margin:22px 0;font:23px/1.5 Georgia,serif;color:#fff2e9}.insp-keepsakes label{display:block;font-size:12px;color:#d5c6dc;margin:15px 0 7px}.insp-keepsakes input,.insp-keepsakes textarea{display:block;width:100%;background:#0002;border:1px solid #ffffff30;border-radius:12px;padding:12px;font:14px/1.6 system-ui;color:#fff;color-scheme:dark}.insp-keepsakes textarea{resize:vertical;margin-bottom:16px}.insp-keepsakes input:focus-visible,.insp-keepsakes textarea:focus-visible{outline:2px solid var(--iq-accent);outline-offset:3px}.insp-keepsakes [data-affection][aria-pressed=true]{color:var(--iq-bg)!important;background:var(--iq-accent)!important}.insp-keepsakes button{font-size:11px!important}.insp-saved-letters{margin:0 0 40px}.insp-letter-summary h3{font:22px Georgia,serif;margin:0}.insp-letter-summary p{font:13px/1.7 system-ui}.insp-letter-summary time{font-size:10px;color:#c1b0c4}#inspReadLetter{width:min(600px,calc(100% - 32px));max-height:85svh;overflow:auto;border:1px solid #b99aca;border-radius:24px;background:#281a34;color:#fff2e9;padding:28px}#inspReadLetter::backdrop{background:#120b20ba}.insp-letter-dialog-top{display:flex;align-items:flex-start;justify-content:space-between;gap:15px}.insp-letter-dialog-top h2{font:29px/1.2 Georgia,serif;margin:0;overflow-wrap:anywhere}#inspReadText{white-space:pre-wrap;overflow-wrap:anywhere;font:18px/1.9 Georgia,serif;margin-top:24px}@media(max-width:720px){.insp-keepsakes{grid-template-columns:1fr}.insp-keepsakes article{padding:22px}}`;
let affectionCategory='gentle',lastAffection='';
keepsakes.addEventListener('click',e=>{const button=e.target.closest('[data-affection]');if(!button)return;affectionCategory=button.dataset.affection;for(const item of keepsakes.querySelectorAll('[data-affection]'))item.setAttribute('aria-pressed',String(item===button));});
$('inspOpenJar').onclick=()=>{const pool=affection[affectionCategory].notes.filter(note=>note!==lastAffection);lastAffection=pool[Math.floor(Math.random()*pool.length)];$('inspAffection').textContent=lastAffection;$('inspCopyAffection').disabled=false;};
$('inspCopyAffection').onclick=async()=>{try{await navigator.clipboard.writeText(lastAffection+'\n— Aliny Inspira');status('Bilhetinho copiado com carinho. 💜');}catch{status('Selecione o bilhetinho para copiar pelo menu do navegador.');}};
function letterItems(){return Array.isArray(savedData.letters)?savedData.letters.filter(letter=>letter&&typeof letter.id==='string'&&typeof letter.title==='string'&&typeof letter.text==='string'):[];}
function clearLetterForm(){ $('inspLetterForm').reset();$('inspLetterStatus').textContent='';if($('inspReadLetter').open)$('inspReadLetter').close();$('inspReadTitle').textContent='';$('inspReadDate').textContent='';$('inspReadText').textContent='';}
function dateLabel(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return '';const date=new Date(value+'T12:00:00');return Number.isNaN(date.getTime())?'':date.toLocaleDateString('pt-BR');}
function renderLetters(){const list=letterItems();$('inspLetters').innerHTML=!loaded?'<p class="insp-empty">Sincronize para carregar suas cartas.</p>':list.length?list.map(letter=>`<article class="insp-card insp-letter-summary"><span>♡ CARTA PARA O FUTURO</span><h3>${esc(letter.title)}</h3>${dateLabel(letter.date)?`<time datetime="${esc(letter.date)}">Para reler em ${esc(dateLabel(letter.date))}</time>`:'<span>Para reler no seu tempo</span>'}<p>${esc(letter.text.slice(0,100))}${letter.text.length>100?'…':''}</p><div class="insp-card-actions"><button type="button" data-read-letter="${esc(letter.id)}">Abrir minha carta</button></div></article>`).join(''):'<p class="insp-empty">Sua primeira carta pode começar com uma frase simples.<br>Escreva acima e guarde um pedacinho de hoje.</p>';}
$('inspLetters').onclick=e=>{const button=e.target.closest('[data-read-letter]');if(!button)return;const letter=letterItems().find(item=>item.id===button.dataset.readLetter);if(!letter)return;$('inspReadTitle').textContent=letter.title;$('inspReadText').textContent=letter.text;$('inspReadDate').textContent=dateLabel(letter.date)?'Uma data para reler: '+dateLabel(letter.date):'Para reler no seu tempo';$('inspReadLetter').showModal();};
$('inspCloseLetter').onclick=()=>$('inspReadLetter').close();
$('inspLetterForm').onsubmit=async e=>{e.preventDefault();const message=$('inspLetterStatus');if(busy){message.textContent='Aguarde a sincronização terminar e tente guardar sua carta novamente.';return;}if(!loaded){message.textContent='Clique em Sincronizar antes de guardar. Seu texto continua aqui.';return;}const title=$('inspLetterTitle').value.trim(),text=$('inspLetterText').value.trim();if(!title||!text){message.textContent='Preencha o título e a mensagem para guardar sua carta.';return;}if(letterItems().length>=50){message.textContent='Você já guardou 50 cartas. Seu texto continua aqui para você copiar.';return;}const letter={id:crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join(''),title,text,date:$('inspLetterDate').value,createdAt:new Date().toISOString()},next={...savedData,favorites:[...favorites],letters:[letter,...letterItems()]},requestGeneration=generation;setBusy(true);$('inspSaveLetter').disabled=true;message.textContent='Guardando sua carta…';try{const response=await window.alinyAuth.api('/api/inspira',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,data:next})});if(requestGeneration!==generation)return;if(response.status===409){loaded=false;throw Error('Sua conta mudou em outro dispositivo. Sincronize e tente guardar novamente. Seu texto continua aqui.');}if(!response.ok)throw Error('Não consegui guardar online. Seu texto continua aqui; tente novamente.');const result=await response.json();if(requestGeneration!==generation)return;savedData=next;revision=result.revision;$('inspLetterForm').reset();renderLetters();message.textContent='Sua carta foi guardada na sua conta. Você pode reler quando quiser. 💜';}catch(error){if(requestGeneration===generation)message.textContent=error.message;}finally{if(requestGeneration===generation){setBusy(false);$('inspSaveLetter').disabled=false;}}};
window.addEventListener('aliny-close-inspira',clearLetterForm);
new MutationObserver(()=>{if(root.hidden)clearLetterForm();}).observe(root,{attributes:true,attributeFilter:['hidden']});
renderLetters();

/* Gentle daily prompts, a personal color journal, and saved achievements. */
const careDate=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo'}).format(new Date());
const careId=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join('');
const careColors={lilac:{name:'Lilás',hex:'#c6a3ec'},rose:{name:'Rosa',hex:'#e5a9c2'},blue:{name:'Azul',hex:'#97bddc'},sage:{name:'Verde',hex:'#b2cea7'},gold:{name:'Dourado',hex:'#e7cb89'},peach:{name:'Pêssego',hex:'#e7b49b'}};
const careChallenges=[
{id:'music',text:'Separe cinco minutos para ouvir uma música que você gosta.',detail:'Vale uma música inteira ou só um trechinho. Escolha o que combina com hoje.'},
{id:'kindness',text:'Escreva uma frase gentil para você.',detail:'Pode ser algo simples, como “eu posso ir no meu tempo”.'},
{id:'pause',text:'Reserve alguns minutos para uma pausa sem tarefas.',detail:'Você escolhe como descansar e quanto tempo faz sentido agora.'},
{id:'notice',text:'Repare em uma coisa bonita ao seu redor.',detail:'Uma cor, uma luz ou um detalhe pequeno já pode virar esse momento.'},
{id:'littlejoy',text:'Escolha uma coisa pequena que você gostaria de fazer por prazer.',detail:'Não precisa produzir nada. Só algo de que você goste.'},
{id:'proud',text:'Lembre de uma coisa que você aprendeu ou conseguiu fazer.',detail:'Se quiser, guarde esse passo na sua caixinha “Eu consegui”.'},
{id:'comfort',text:'Deixe um cantinho um pouco mais aconchegante para você.',detail:'Pode ser ajustar a cadeira, arrumar uma almofada ou escolher uma luz agradável.'},
{id:'thanks',text:'Pense em um momento de hoje que você quer guardar.',detail:'Pode ser pequenininho. Se nenhuma ideia vier agora, você pode voltar depois.'},
{id:'future',text:'Escreva um desejo simples para os próximos dias.',detail:'Um lembrete carinhoso, sem prazo e sem cobrança.'},
{id:'choose',text:'Escolha fazer uma coisa de cada vez por alguns minutos.',detail:'Um começo pequeno já é suficiente para este momento.'},
{id:'favorite',text:'Dê um espaço no seu dia para algo que é a sua cara.',detail:'Uma cor, uma música, uma história ou uma roupa de que você gosta.'},
{id:'recognize',text:'Reconheça um esforço seu que costuma passar despercebido.',detail:'Tentar, pedir companhia ou respeitar um limite também merecem reconhecimento.'}
];
let careToday=careDate(),careChallengeIndex=0,careSelectedColor='lilac',lastWinId='',careReady=false;
function dailyChallengeIndex(date){let hash=0;for(const c of date)hash=(hash*31+c.charCodeAt(0))>>>0;return hash%careChallenges.length;}
